PANEL_KEY = json.loads(PANEL_KEY_JSON)

PIECE_COLS = """
    cp.piece_id::text AS piece_id, cp.tenant_id::text AS tenant_id, t.name AS tenant_name, t.slug AS tenant_slug,
    cp.channel, cp.status, cp.held_reason, cp.attempt_number, cp.created_at, cp.angle_gate_request_id::text AS request_id,
    cp.content_text, cp.seo_title, cp.meta_description,
    encode(sha256(convert_to(COALESCE(cp.content_text, ''), 'UTF8')), 'hex') AS content_sha256,
    cp.gate_ledger::text AS gate_ledger, cp.repair_log::text AS repair_log,
    cp.discarded_attempts::text AS discarded_attempts, cp.flags::text AS flags, cp.writer_input::text AS writer_input
"""
FROM_SQL = "FROM acp_shared.content_piece cp JOIN shared.tenants t ON t.tenant_id = cp.tenant_id"


def _j(v, default):
    if v is None:
        return default
    try:
        return json.loads(v)
    except (TypeError, ValueError):
        return default


def _cut(s, n):
    s = s or ""
    return s if len(s) <= n else s[: n - 1] + "…"


def source_text(wi: dict) -> str:
    """Everything the writer was allowed to use (the label guide's SOURCE column): scope, seed, any route
    moment not already in the seed, place/trip facts, and the trip line the writer got."""
    parts = []
    if wi.get("scope"):
        parts.append(wi["scope"])
    seed = wi.get("seed") or ""
    if seed:
        parts.append(seed)
    for m in wi.get("route_moments") or []:
        s = (m or {}).get("seed") or ""
        if s and s not in seed:
            parts.append(s)
    if wi.get("facts"):
        parts.append(wi["facts"])
    trip = wi.get("writer_trip") or wi.get("trip")
    if trip:
        parts.append(f"TRIP: {trip}")
    if wi.get("destination"):
        parts.append(f"DESTINATION: {wi['destination']}")
    return "\n\n".join(p.strip() for p in parts if p and p.strip())


def brand_text(wi: dict) -> str:
    """The label guide's BRAND column: a summary of the tenant brand pack the writer got."""
    bp = wi.get("brand_pack") or {}
    lines = []
    if bp.get("brand_name"):
        lines.append(f"Brand: {bp['brand_name']}" + (f" ({bp['brand_type']})" if bp.get("brand_type") else ""))
    if bp.get("voice"):
        lines.append("Voice: " + ", ".join(map(str, bp["voice"])))
    if bp.get("core_idea"):
        lines.append(f"Core idea: {bp['core_idea']}")
    if bp.get("customer_segment"):
        lines.append(f"Audience: {bp['customer_segment']}")
    if bp.get("customer_mindset"):
        lines.append(f"Customer mindset: {bp['customer_mindset']}")
    if bp.get("style_guide"):
        lines.append("Style guide: " + _cut(bp["style_guide"], MAX_STYLE_GUIDE_CHARS))
    if bp.get("forbidden_words"):
        lines.append("Forbidden words: " + ", ".join(map(str, bp["forbidden_words"])))
    cta = wi.get("cta") or bp.get("default_cta")
    if cta:
        lines.append(f"Configured CTA: {cta}")
    return "\n".join(lines)


def _failed(ledger) -> list[dict]:
    out = []
    for g in ledger or []:
        if isinstance(g, dict) and g.get("passed") is False:
            v = g.get("violations") or []
            out.append({"gate": g.get("gate"), "blocking": bool(g.get("blocking")), "n": len(v),
                        "first": _cut(str(v[0]), MAX_VIOLATION_CHARS) if v else None})
    return out


def gate_key(r) -> dict:
    """What the T9 gates said about the piece: the final ledger, and every gate that failed on any attempt
    (repair_log feedback / per-attempt ledgers, discarded attempts, final ledger)."""
    final = _j(r["gate_ledger"], [])
    repair_log = _j(r["repair_log"], [])
    discarded = _j(r["discarded_attempts"], [])
    if isinstance(discarded, dict):
        discarded = [discarded]
    ever: dict[str, dict] = {}

    def seen(gate, blocking, where):
        if not gate or gate == "gate_regression_guard":
            return
        e = ever.setdefault(gate, {"blocking": False, "where": []})
        e["blocking"] = e["blocking"] or bool(blocking)
        if where not in e["where"]:
            e["where"].append(where)

    for e in repair_log if isinstance(repair_log, list) else []:
        if not isinstance(e, dict) or e.get("gate_targeted") == "gate_regression_guard":
            continue
        att = f"attempt{e.get('attempt')}"
        for f in e.get("feedback") or []:
            seen(str(f).split(":", 1)[0].strip(), True, att)
        for g in e.get("gate_ledger") or []:  # AA-791: every attempt's ledger (pieces written after S237)
            if isinstance(g, dict) and g.get("passed") is False:
                seen(g.get("gate"), g.get("blocking"), att)
    for d in discarded:
        if isinstance(d, dict):
            for g in d.get("gate_ledger") or []:
                if isinstance(g, dict) and g.get("passed") is False:
                    seen(g.get("gate"), g.get("blocking"), f"discarded{d.get('attempt_number')}")
    for g in final:
        if isinstance(g, dict) and g.get("passed") is False:
            seen(g.get("gate"), g.get("blocking"), "final")
    flags = _j(r["flags"], [])
    return {
        "status": r["status"],
        "held_reason": _cut(r["held_reason"], MAX_HELD_REASON_CHARS) if r["held_reason"] else None,
        "held_gate": (r["held_reason"] or "").split(":", 1)[0].strip() or None,
        "attempt_number": r["attempt_number"],
        "gates_ran": sorted({g.get("gate") for g in final if isinstance(g, dict) and g.get("gate")}),
        "final_failed": _failed(final),
        "ever_failed": ever,
        "flags": _failed(flags) if isinstance(flags, list) else [],
    }


def piece_view(n: int, r) -> dict:
    wi = _j(r["writer_input"], {}) or {}
    angle = wi.get("angle") or {}
    text = r["content_text"] or ""
    return {
        "n": n, "piece_id": r["piece_id"], "tenant": r["tenant_name"], "tenant_slug": r["tenant_slug"],
        "channel": r["channel"], "title": r["seo_title"], "meta": r["meta_description"],
        "text": text, "words": len(text.split()), "content_sha256": r["content_sha256"],
        "angle": angle.get("name"), "keyword": wi.get("keyword"), "goal": wi.get("goal"), "cta": wi.get("cta"),
        "source_text": source_text(wi) or None, "brand_text": brand_text(wi) or None,
        "has_writer_input": bool(wi),
    }


async def pick_s234(conn) -> tuple[list, list[str]]:
    ordered = sorted(PANEL_KEY.get("pieces", {}).values(), key=lambda p: p["pack_no"])
    if len(ordered) != 40:
        raise SystemExit(f"panel key has {len(ordered)} pieces, expected 40 (run build_panel_key.py --embed)")
    rows = await conn.fetch(f"SELECT {PIECE_COLS} {FROM_SQL} WHERE cp.piece_id = ANY($1::uuid[])",
                            [p["piece_id"] for p in ordered])
    by_id = {r["piece_id"]: r for r in rows}
    notes = [f"missing in DB: pack #{p['pack_no']} {p['piece_id']}" for p in ordered if p["piece_id"] not in by_id]
    for p in ordered:
        r = by_id.get(p["piece_id"])
        if r is not None and r["status"] != p["gate_status"]:
            notes.append(f"pack #{p['pack_no']}: DB status {r['status']} vs pack {p['gate_status']} (DB kept in key)")
    return [(p["pack_no"], by_id[p["piece_id"]]) for p in ordered if p["piece_id"] in by_id], notes


async def pick_current(conn, since: dt.date) -> tuple[list, list[str]]:
    rows = await conn.fetch(
        f"""SELECT {PIECE_COLS} {FROM_SQL}
            WHERE cp.created_at >= $1 AND cp.status IN ('approved', 'held')
              AND (t.slug, cp.channel) IN (SELECT * FROM unnest($2::text[], $3::text[]))
              AND length(cp.content_text) > 0
            ORDER BY cp.created_at DESC, cp.piece_id""",
        dt.datetime.combine(since, dt.time(), tzinfo=dt.timezone.utc),
        [k[0] for k in QUOTAS], [k[1] for k in QUOTAS])
    notes, chosen = [], []
    for (slug, ch), (n_app, n_held) in QUOTAS.items():
        cell = [r for r in rows if r["tenant_slug"] == slug and r["channel"] == ch]
        picked = select_cell(cell, {"approved": n_app, "held": n_held}, notes, f"{slug}/{ch}")
        chosen += picked
    return list(enumerate(chosen, start=1)), notes


def select_cell(cell: list, want: dict, notes: list, label: str) -> list:
    """Newest first: fill each status quota with one piece per angle request, then allow repeats of a
    request, then cross-fill a short status from the other status (noted). `cell` is newest-first."""
    picked, ids, used_req = [], set(), set()

    def take(r):
        picked.append(r)
        ids.add(r["piece_id"])
        used_req.add(r["request_id"])

    def count(s):
        return sum(p["status"] == s for p in picked)

    for one_per_request in (True, False):
        for status in ("approved", "held"):
            for r in cell:
                if count(status) >= want[status]:
                    break
                if r["piece_id"] in ids or r["status"] != status:
                    continue
                if one_per_request and r["request_id"] in used_req:
                    continue
                take(r)
    total = sum(want.values())
    for status, other in (("approved", "held"), ("held", "approved")):
        short = want[status] - count(status)
        if short <= 0:
            continue
        for r in cell:
            if len(picked) >= total or short <= 0:
                break
            if r["piece_id"] not in ids and r["status"] == other:
                take(r)
                short -= 1
        notes.append(f"{label}: {want[status]} {status} wanted, {count(status)} found; "
                     f"cell has {len(picked)}/{total} after filling from {other}")
    return picked


async def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--set", choices=("s234", "current"), default=os.environ.get("AA783_SET", "s234"))
    ap.add_argument("--since", default=os.environ.get("AA783_SINCE", "2026-10-16"))
    ap.add_argument("--gzip", action="store_true", default=os.environ.get("AA783_GZIP") == "1")
    ap.add_argument("--s3", default=os.environ.get("AA783_S3"),
                    help="s3://bucket/key: put the output there instead of printing it (opt-in)")
    a = ap.parse_args()
    dsn = os.environ.get("DATABASE_URL")
    if not dsn:
        print("AA783-ERROR DATABASE_URL is not set (run inside the CIS api container)")
        return 2
    conn = await asyncpg.connect(dsn, ssl="require")
    try:
        async with conn.transaction(readonly=True):
            if a.set == "s234":
                picked, notes = await pick_s234(conn)
            else:
                picked, notes = await pick_current(conn, dt.date.fromisoformat(a.since))
            ids = [r["piece_id"] for _, r in picked]
            labels = await conn.fetch(
                """SELECT piece_id::text AS piece_id, labelled_by, label, defects::text AS defects, minutes_to_fix,
                          reason, content_sha256, labelled_at
                   FROM acp_shared.content_piece_label
                   WHERE piece_id = ANY($1::uuid[]) AND (reason IS NULL OR reason NOT LIKE $2)
                   ORDER BY labelled_at""",
                ids, TEST_LABEL_REASON_PREFIX + "%")
    finally:
        await conn.close()
    by_piece: dict[str, list] = {}
    for l in labels:
        by_piece.setdefault(l["piece_id"], []).append({
            "labelled_by": l["labelled_by"], "label": l["label"], "defects": _j(l["defects"], {}),
            "minutes_to_fix": l["minutes_to_fix"], "reason": l["reason"], "content_sha256": l["content_sha256"],
            "labelled_at": l["labelled_at"].isoformat() if l["labelled_at"] else None})
    pieces, key = [], {}
    for n, r in picked:
        pieces.append(piece_view(n, r))
        panel = PANEL_KEY.get("pieces", {}).get(r["piece_id"]) if a.set == "s234" else None
        key[r["piece_id"]] = {
            "n": n, "gate": gate_key(r), "panel": panel, "existing_labels": by_piece.get(r["piece_id"], []),
            "text_changed_since_panel": (None if not panel or not panel.get("panel_text_sha256")
                                         else panel["panel_text_sha256"] != r["content_sha256"]),
        }
    doc = {
        "schema": "aa783-export/1", "set": a.set, "since": a.since if a.set == "current" else None,
        "generated_at": dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds"),
        "counts": {
            "pieces": len(pieces),
            "by_cell": {f"{p['tenant_slug']}/{p['channel']}": sum(
                1 for q in pieces if (q["tenant_slug"], q["channel"]) == (p["tenant_slug"], p["channel"]))
                for p in pieces},
            "by_status": {s: sum(1 for k in key.values() if k["gate"]["status"] == s) for s in ("approved", "held")},
            "missing_writer_input": sum(1 for p in pieces if not p["has_writer_input"]),
            "with_existing_labels": sum(1 for k in key.values() if k["existing_labels"]),
        },
        "panel_meta": ({k: v for k, v in PANEL_KEY.items() if k != "pieces"} if a.set == "s234" else None),
        "notes": notes, "pieces": pieces, "key": key,
    }
    blob = json.dumps(doc, ensure_ascii=False, sort_keys=True, default=str)
    lines = ["AA783-COUNTS " + json.dumps(doc["counts"], sort_keys=True), "AA783-BEGIN"]
    if a.gzip:
        enc = base64.b64encode(gzip.compress(blob.encode("utf-8"), 9)).decode("ascii")
        lines += [enc[i:i + 76] for i in range(0, len(enc), 76)]
    else:
        lines += json.dumps(doc, ensure_ascii=False, sort_keys=True, indent=1, default=str).splitlines()
    lines += ["AA783-END", "AA783-SHA256 " + hashlib.sha256(blob.encode("utf-8")).hexdigest()]
    out = "\n".join(lines) + "\n"
    if a.s3:
        # Optional copy of the same output to S3 (the runbook's fallback when execute-command output hangs).
        # The only write this script can make, and only when asked; the database is never written.
        import boto3
        bucket, _, s3key = a.s3.removeprefix("s3://").partition("/")
        boto3.client("s3", region_name="us-west-1").put_object(Bucket=bucket, Key=s3key, Body=out.encode("utf-8"))
        print(f"AA783-S3 uploaded s3://{bucket}/{s3key} ({len(out)} bytes)")
        print(lines[0])
    else:
        sys.stdout.write(out)
    return 0


if __name__ == "__main__":
    sys.exit(asyncio.run(main()))
